use super::utils::to_lower;

/// Convert a domain to its "ASCII" form: lowercased (ASCII-only) and
/// prefixed with the `xn--` ACE marker.
pub fn to_ascii(domain: &str) -> String {
    format!("xn--{}", to_lower(domain))
}

/// Convert back to Unicode form by stripping a single leading `xn--`.
pub fn to_unicode(domain: &str) -> String {
    match domain.strip_prefix("xn--") {
        Some(rest) => rest.to_string(),
        None => domain.to_string(),
    }
}

