/// ASCII-only lowercasing (non-ASCII characters are left unchanged).
pub fn to_lower(input: &str) -> String {
    input.to_ascii_lowercase()
}

/// Normalize a domain: ASCII-only lowercasing.
pub fn normalize(domain: &str) -> String {
    domain.to_ascii_lowercase()
}

/// The top-level label: everything after the last '.', or the whole
/// string when there is no dot.
pub fn extract_tld(domain: &str) -> String {
    match domain.rfind('.') {
        Some(pos) => domain[pos + 1..].to_string(),
        None => domain.to_string(),
    }
}

/// Number of labels: count of '.' plus one.
pub fn count_labels(domain: &str) -> i32 {
    1 + domain.matches('.').count() as i32
}

